import{STORAGE_KEY,STAGES,KINDS,CATEGORIES,PRIORITIES,emptyState,scope,totals,grantTotals,alerts,blankGrant,fromCatalog,validateState,amount,cents,sum,alive,grantsCSV,costsCSV,allocationsCSV,projectsCSV}from './model.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=prefix=>prefix+'_'+crypto.randomUUID();
const euro=n=>n===null||n===undefined?'—':new Intl.NumberFormat('ca-ES',{style:'currency',currency:'EUR',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const fmt=d=>d?new Date(d+'T12:00:00Z').toLocaleDateString('ca-ES',{timeZone:'Europe/Madrid'}):'—';
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(new Date());
let state=emptyState(),catalog=[],grantId=null,projectId=null,costId=null,catalogDraft=null,draftAlloc={},storageBroken=false;
try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)state=validateState(JSON.parse(raw));}catch{storageBroken=true;$('save-status').textContent='No s’ha pogut recuperar la còpia local. No desis canvis abans d’intentar importar una còpia vàlida.';}
const selects=(el,values,first='')=>{el.innerHTML=(first?'<option value="">'+esc(first)+'</option>':'')+values.map(v=>{const [id,label]=Array.isArray(v)?v:[v,v];return'<option value="'+esc(id)+'">'+esc(label)+'</option>';}).join('');};
const field=(form,key)=>form.elements.namedItem(key);
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').hidden=true,6000);}
function context(){return{year:$('year').value,projectId:$('project-filter').value};}
function view(){return scope(state,context());}
function save(next){const clean=validateState(next);if(storageBroken&&!confirm('No s’ha pogut llegir el seguiment anterior. Vols començar una nova matriu i substituir la dada local?'))return false;try{localStorage.setItem(STORAGE_KEY,JSON.stringify(clean));storageBroken=false;$('save-status').textContent='Canvis desats en aquest navegador · exporta una còpia JSON després de cada revisió.';}catch{$('save-status').textContent='No s’ha pogut desar al navegador. Exporta ara una còpia JSON per conservar els canvis.';}state=clean;render();return true;}
function renderContext(){const y=$('year').value,p=$('project-filter').value;const years=[...new Set([new Date().getFullYear(),...state.projects.map(p=>p.year),...state.grants.map(g=>g.year)])].sort((a,b)=>b-a);selects($('year'),years.map(y=>[String(y),String(y)]),'Tots els anys');$('year').value=years.map(String).includes(y)?y:'';const projects=state.projects.filter(p=>!$('year').value||String(p.year)===$('year').value);selects($('project-filter'),projects.map(p=>[p.id,p.name+' · '+p.year]),'Tots els projectes');$('project-filter').value=projects.some(x=>x.id===p)?p:'';}
function showContext(year,pid=''){renderContext();$('year').value=String(year);renderContext();$('project-filter').value=pid;render();}
function metric(label,value,help,tone=''){return'<article class="metric '+tone+'"><span>'+label+'</span><strong>'+euro(value)+'</strong><small>'+help+'</small></article>';}
function renderOverview(){const s=view(),t=totals(s);$('overview').innerHTML=metric('Pressupost de despeses',t.planned,s.projects.length+' projectes · previst')+metric('Sol·licitat en actiu',t.requested,'Candidatures no descartades')+metric('Subvencions concedides',t.awarded,'Imports registrats, sense estimacions')+metric('Subvencions cobrades',t.received,'Pendent de cobrar: '+euro(t.pendingCollection))+metric('Despesa real / pagada',t.actual,'Ja pagat: '+euro(t.paid))+metric('Pendent de finançar',t.gap,'Per projecte, amb aportació pròpia i altres ingressos',t.gap>0?'amber':'');}
function renderGrants(){const s=view(),q=$('search').value.toLocaleLowerCase('ca'),list=s.grants.filter(g=>(!q||[g.name,g.organism,g.owner,g.reference].join(' ').toLocaleLowerCase('ca').includes(q))&&(!$('stage-filter').value||g.stage===$('stage-filter').value)&&(!$('priority-filter').value||g.priority===$('priority-filter').value)).sort((a,b)=>(a.deadline||'9999').localeCompare(b.deadline||'9999')||a.name.localeCompare(b.name,'ca'));$('row-count').textContent=list.length+' de '+s.grants.length+' candidatures';$('grant-rows').innerHTML=list.length?list.map(g=>{const p=state.projects.find(p=>p.id===g.projectId),t=grantTotals(state,g);return'<tr><td><button class="row-title" data-grant="'+g.id+'">'+esc(g.name)+'</button><div class="row-meta">'+esc(g.organism||'Organisme pendent')+'</div><span class="tag">'+esc(g.kind)+'</span> <span class="row-meta">'+esc(g.priority)+'</span></td><td>'+esc(p?.name||'Sense projecte')+'<div class="row-meta">'+esc(g.entity||'Entitat pendent')+' · '+g.year+'</div></td><td><span class="tag '+(['Concedida','En execució','Justificada','Tancada'].includes(g.stage)?'green':'')+'">'+esc(g.stage)+'</span><div class="row-meta">'+(g.verified?'Requisits revisats per tu':'Requisits pendents')+'</div></td><td class="money">'+euro(g.requested)+'</td><td class="money">'+euro(g.awarded)+'</td><td class="money">'+euro(g.received)+'</td><td class="money '+(t.pending!==null&&t.pending<0?'danger':'')+'">'+euro(t.pending)+'</td><td class="money">'+euro(t.planned)+'<div class="row-meta">Real: '+euro(t.actual)+'</div></td><td>'+fmt(g.deadline)+'</td><td>'+fmt(g.justification)+'</td><td>'+esc(g.owner||'Sense responsable')+'<div class="row-meta">'+esc(g.nextAction)+'</div>'+(g.nextDate?'<div class="row-meta">'+fmt(g.nextDate)+'</div>':'')+'</td><td><button class="button compact" data-grant="'+g.id+'">Edita ↗</button></td></tr>';}).join(''):'<tr><td colspan="12"><div class="empty"><h3>'+(!state.grants.length?'La matriu està preparada per començar.':'No hi ha candidatures amb aquests filtres.')+'</h3><p>'+(!state.grants.length?'Crea un projecte i afegeix una convocatòria pròpia o incorpora-la des del radar. No hi ha concessions ni imports ficticis.':'Canvia els filtres o afegeix una nova candidatura.')+'</p><button class="button primary" data-action="new-grant">＋ Afegir subvenció</button> <button class="button" data-action="catalog">Incorporar del radar</button></div></td></tr>';}
function renderProjects(){const s=view();$('project-cards').innerHTML=s.projects.length?s.projects.map(p=>{const t=totals(scope(state,{projectId:p.id})),pct=t.planned?Math.min(100,t.secured/t.planned*100):0;return'<article class="panel project-card"><div class="project-top"><span class="tag">'+p.year+'</span><button class="text-button" data-project="'+p.id+'">Edita projecte ↗</button></div><h3>'+esc(p.name)+'</h3><p class="small muted">'+esc(p.entity||'Entitat pendent')+' · '+esc(p.owner||'Responsable pendent')+'</p><div class="project-figures"><div><span>Previst</span><strong>'+euro(t.planned)+'</strong></div><div><span>Compromès</span><strong>'+euro(t.secured)+'</strong></div><div><span>Falta finançar</span><strong>'+euro(t.gap)+'</strong></div></div><label class="progress-label">Cobertura del pressupost previst: '+(t.planned?Math.round(pct)+'%':'pendent de pressupostar')+'<progress max="100" value="'+pct+'"></progress></label><p class="small">Ajuts concedits: '+euro(t.awarded)+' · Aportació pròpia: '+euro(t.own)+' · Altres ingressos: '+euro(t.other)+'</p><p class="cash '+(t.cashDifference<0?'danger':'')+'">Cobraments registrats − pagaments: <b>'+euro(t.cashDifference)+'</b></p><button class="button compact" data-add-cost="'+p.id+'">＋ Afegir despesa</button></article>';}).join(''):'<div class="panel empty"><h3>Comença amb el pressupost d’un projecte.</h3><p>Afegeix-ne les despeses i després vincula-hi les subvencions.</p><button class="button primary" data-action="new-project">＋ Crear projecte</button></div>';
$('cost-rows').innerHTML=s.costs.length?s.costs.map(c=>{const a=state.allocations.filter(a=>a.costId===c.id&&alive(state.grants.find(g=>g.id===a.grantId))),p=state.projects.find(p=>p.id===c.projectId),variance=c.actual!==null&&c.planned!==null?(cents(c.actual)-cents(c.planned))/100:null;return'<tr><td>'+esc(p.name)+'<div class="row-meta">'+esc(c.category)+'</div></td><td><button class="row-title" data-cost="'+c.id+'">'+esc(c.label)+'</button></td><td class="money">'+euro(c.planned)+'</td><td class="money">'+euro(c.actual)+'</td><td class="money">'+euro(c.paid)+'</td><td class="money">'+euro(sum(a,'planned'))+'</td><td class="money">'+euro(sum(a,'actual'))+'</td><td class="money '+(variance>0?'danger':'')+'">'+euro(variance)+'</td><td><button class="button compact" data-cost="'+c.id+'">Edita ↗</button></td></tr>';}).join(''):'<tr><td colspan="9" class="empty">Encara no hi ha despeses en aquest àmbit. Pots afegir partides globals o línies de factures i nòmines.</td></tr>';}
function renderCalendar(){const events=[];for(const g of view().grants.filter(alive)){if(g.deadline&&['En estudi','En preparació'].includes(g.stage))events.push({date:g.deadline,label:'Sol·licitud',g});if(g.justification&&!['Justificada','Tancada'].includes(g.stage))events.push({date:g.justification,label:'Justificació',g});if(g.nextDate)events.push({date:g.nextDate,label:'Acció interna',g});if(g.end&&['Concedida','En execució'].includes(g.stage))events.push({date:g.end,label:'Final d’execució',g});}events.sort((a,b)=>a.date.localeCompare(b.date));$('calendar').innerHTML=events.length?events.map(e=>'<div class="calendar-row"><time class="'+(e.date<today()?'danger':'')+'" datetime="'+e.date+'">'+fmt(e.date)+'</time><div><span class="eyebrow">'+e.label+(e.date<today()?' · DATA PASSADA':'')+'</span><button class="row-title" data-grant="'+e.g.id+'">'+esc(e.g.name)+'</button><p class="row-meta">'+esc(e.label==='Acció interna'?e.g.nextAction:e.g.owner)+'</p></div></div>').join(''):'<p class="empty small">Els terminis apareixeran aquí quan els registris a les candidatures.</p>';}
function renderAlerts(){const s=view(),gs=new Set(s.grants.map(g=>g.id)),ps=new Set(s.projects.map(p=>p.id)),cs=new Set(s.costs.map(c=>c.id));const list=alerts(state).filter(a=>a.kind==='grant'?gs.has(a.id):a.kind==='project'?ps.has(a.id):cs.has(a.id));$('alert-count').textContent=list.length;$('alerts').innerHTML=list.length?list.map(a=>'<button class="alert '+a.level+'" data-'+a.kind+'="'+a.id+'"><span aria-hidden="true">'+(a.level==='danger'?'!':'ⓘ')+'</span><span>'+esc(a.text)+'</span></button>').join(''):'<p class="empty small">'+(!state.grants.length&&!state.costs.length?'Encara no hi ha dades per revisar.':'No s’han detectat incoherències entre les dades registrades. Això no valida el compliment de les bases.')+'</p>';}
function render(){renderContext();renderOverview();renderGrants();renderProjects();renderCalendar();renderAlerts();}
function setForm(form,obj){for(const [key,value]of Object.entries(obj)){const el=field(form,key);if(!el)continue;if(el.type==='checkbox')el.checked=!!value;else el.value=value??'';}}
function grantProjects(){const f=$('grant-form'),selected=field(f,'projectId').value,y=Number(field(f,'year').value);selects(field(f,'projectId'),state.projects.filter(p=>p.year===y).map(p=>[p.id,p.name]),'Sense projecte assignat');field(f,'projectId').value=state.projects.some(p=>p.id===selected&&p.year===y)?selected:'';}
function collectDraft(){for(const row of $('allocation-editor').querySelectorAll('[data-allocation-cost]')){draftAlloc[row.dataset.allocationCost]={planned:amount(row.querySelector('[data-plan]').value),actual:amount(row.querySelector('[data-actual]').value),confirmed:row.querySelector('[data-confirmed]').checked};}}
function renderAllocations(){const selected=field($('grant-form'),'projectId').value,costs=state.costs.filter(c=>c.projectId===selected);$('allocation-editor').innerHTML=selected?(costs.length?'<div class="table-scroll"><table class="allocation-table"><thead><tr><th>Despesa</th><th>Cost previst / real</th><th>Imputació prevista (€)</th><th>Imputació real (€)</th><th>Elegibilitat revisada</th></tr></thead><tbody>'+costs.map(c=>{const a=draftAlloc[c.id]??{planned:null,actual:null,confirmed:false};return'<tr data-allocation-cost="'+c.id+'"><td>'+esc(c.label)+'<div class="row-meta">'+esc(c.category)+'</div></td><td>'+euro(c.planned)+'<div class="row-meta">Real: '+euro(c.actual)+'</div></td><td><input data-plan type="number" min="0" max="1000000000" step="0.01" value="'+(a.planned??'')+'" aria-label="Imputació prevista de '+esc(c.label)+'"></td><td><input data-actual type="number" min="0" max="1000000000" step="0.01" value="'+(a.actual??'')+'" aria-label="Imputació real de '+esc(c.label)+'"></td><td><label class="checkbox-label"><input data-confirmed type="checkbox" '+(a.confirmed?'checked':'')+'> Revisada</label></td></tr>';}).join('')+'</tbody></table></div>':'<p class="inline-note">Aquest projecte encara no té despeses. Desa la candidatura i afegeix-les a «Pressupostos»; després podràs imputar-les aquí.</p>'):'<p class="inline-note">Assigna un projecte per vincular aquesta subvenció a les seves despeses.</p>';}
function openGrant(id=null,draft=null){grantId=id;catalogDraft=draft;const g=id?state.grants.find(g=>g.id===id):draft??blankGrant(Number($('year').value)||new Date().getFullYear());const f=$('grant-form');f.reset();selects(field(f,'kind'),KINDS);selects(field(f,'stage'),STAGES);selects(field(f,'priority'),PRIORITIES);setForm(f,g);grantProjects();field(f,'projectId').value=g.projectId;draftAlloc={};for(const a of state.allocations.filter(a=>a.grantId===id))draftAlloc[a.costId]={...a};renderAllocations();$('grant-title').textContent=id?'Edita candidatura':'Afegir candidatura';$('delete-grant').hidden=!id;$('grant-error').textContent='';$('grant-dialog').showModal();}
function openProject(id=null){projectId=id;const p=id?state.projects.find(p=>p.id===id):{name:'',entity:'',year:Number($('year').value)||new Date().getFullYear(),owner:'',ownPlanned:null,ownReceived:null,otherCommitted:null,otherReceived:null,notes:''};$('project-form').reset();setForm($('project-form'),p);$('project-title').textContent=id?'Edita projecte':'Crear projecte';$('delete-project').hidden=!id;$('project-error').textContent='';$('project-dialog').showModal();}
function openCost(id=null,pid=''){if(!state.projects.length){toast('Primer crea un projecte per poder-hi afegir despeses.');openProject();return;}costId=id;const c=id?state.costs.find(c=>c.id===id):{projectId:pid||$('project-filter').value||state.projects.find(p=>!$('year').value||String(p.year)===$('year').value)?.id||state.projects[0].id,category:'Personal',label:'',planned:null,actual:null,paid:null,notes:''};const f=$('cost-form');f.reset();selects(field(f,'projectId'),state.projects.map(p=>[p.id,p.name+' · '+p.year]));selects(field(f,'category'),CATEGORIES);setForm(f,c);field(f,'projectId').disabled=!!id&&state.allocations.some(a=>a.costId===id);$('cost-title').textContent=id?'Edita despesa':'Afegir despesa';$('delete-cost').hidden=!id;$('cost-error').textContent='';$('cost-dialog').showModal();}
function renderCatalog(){const q=$('catalog-search').value.toLowerCase(),rows=catalog.filter(r=>['Subvenció','Beca'].includes(r.kind)&&(!q||[r.name,r.area,r.project].join(' ').toLowerCase().includes(q)));$('catalog-list').innerHTML=rows.length?rows.map(r=>'<article class="catalog-row"><div><h3>'+esc(r.name)+'</h3><p>'+esc(r.area)+' · '+esc(r.kind)+' · Estat documental: '+esc(r.status)+'</p><p class="small muted">'+esc(r.amount)+'</p></div><button class="button compact" data-catalog="'+r.id+'">Incorporar</button></article>').join(''):'<p class="inline-note">'+(catalog.length?'No hi ha resultats.':'No s’ha pogut carregar el radar. Pots crear una candidatura manualment.')+'</p>';}
function openCatalog(){renderCatalog();$('catalog-dialog').showModal();}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('grant-form').onsubmit=e=>{e.preventDefault();try{const f=e.currentTarget,g={...(grantId?state.grants.find(g=>g.id===grantId):catalogDraft??blankGrant()),id:grantId??uid('g')};for(const key of ['name','organism','reference','source','projectId','entity','area','kind','stage','priority','owner','deadline','requestDate','resolutionDate','start','end','justification','nextDate','nextAction','notes'])g[key]=field(f,key).value.trim();g.year=Number(field(f,'year').value);g.verified=field(f,'verified').checked;for(const key of ['requested','awarded','received','eligibleBudget','maxRate','maxGrant'])g[key]=amount(field(f,key).value);collectDraft();const next=structuredClone(state);next.grants=grantId?next.grants.map(old=>old.id===grantId?g:old):[...next.grants,g];next.allocations=next.allocations.filter(a=>a.grantId!==g.id);for(const c of next.costs.filter(c=>c.projectId===g.projectId)){const a=draftAlloc[c.id];if(a&&(a.planned!==null||a.actual!==null||a.confirmed))next.allocations.push({id:uid('a'),grantId:g.id,costId:c.id,planned:a.planned,actual:a.actual,confirmed:a.confirmed});}if(save(next)){$('grant-dialog').close();showContext(g.year,g.projectId);toast('Candidatura desada. Revisa els avisos del pressupost.');}}catch(err){$('grant-error').textContent=err.message;}};
$('project-form').onsubmit=e=>{e.preventDefault();try{const f=e.currentTarget,p={id:projectId??uid('p')};for(const k of ['name','entity','owner','notes'])p[k]=field(f,k).value.trim();p.year=Number(field(f,'year').value);for(const k of ['ownPlanned','ownReceived','otherCommitted','otherReceived'])p[k]=amount(field(f,k).value);if(projectId&&state.grants.some(g=>g.projectId===projectId&&g.year!==p.year))throw Error('Aquest projecte té candidatures vinculades a un altre any. Mantén l’any o reassigna primer les candidatures.');const next=structuredClone(state);next.projects=projectId?next.projects.map(old=>old.id===projectId?p:old):[...next.projects,p];if(save(next)){$('project-dialog').close();showContext(p.year,p.id);toast('Projecte desat. Ja pots afegir-hi despeses.');}}catch(err){$('project-error').textContent=err.message;}};
$('cost-form').onsubmit=e=>{e.preventDefault();try{const f=e.currentTarget,c={id:costId??uid('c')};for(const k of ['projectId','category','label','notes'])c[k]=field(f,k).value.trim();for(const k of ['planned','actual','paid'])c[k]=amount(field(f,k).value);const next=structuredClone(state);next.costs=costId?next.costs.map(old=>old.id===costId?c:old):[...next.costs,c];if(save(next)){$('cost-dialog').close();const p=state.projects.find(p=>p.id===c.projectId);showContext(p.year,p.id);toast('Despesa desada. Assigna les imputacions des de cada subvenció.');}}catch(err){$('cost-error').textContent=err.message;}};
$('delete-grant').onclick=()=>{if(grantId&&confirm('Vols eliminar aquesta candidatura i les seves imputacions? Les despeses del projecte es conservaran.')){const next=structuredClone(state);next.grants=next.grants.filter(g=>g.id!==grantId);next.allocations=next.allocations.filter(a=>a.grantId!==grantId);if(save(next))$('grant-dialog').close();}};
$('delete-project').onclick=()=>{if(state.grants.some(g=>g.projectId===projectId)||state.costs.some(c=>c.projectId===projectId)){$('project-error').textContent='El projecte té candidatures o despeses vinculades. Reassigna-les o elimina-les abans d’eliminar-lo.';return;}if(projectId&&confirm('Vols eliminar aquest projecte buit?')){const next=structuredClone(state);next.projects=next.projects.filter(p=>p.id!==projectId);if(save(next))$('project-dialog').close();}};
$('delete-cost').onclick=()=>{if(costId&&confirm('Vols eliminar aquesta despesa i totes les seves imputacions?')){const next=structuredClone(state);next.costs=next.costs.filter(c=>c.id!==costId);next.allocations=next.allocations.filter(a=>a.costId!==costId);if(save(next))$('cost-dialog').close();}};
$('add-grant').onclick=()=>openGrant();$('add-project').onclick=()=>openProject();$('add-cost').onclick=()=>openCost();$('open-catalog').onclick=openCatalog;
document.addEventListener('click',e=>{const b=e.target.closest('[data-close],[data-grant],[data-project],[data-cost],[data-add-cost],[data-action],[data-catalog]');if(!b)return;const d=b.dataset;if(d.close)$(d.close).close();else if(d.grant)openGrant(d.grant);else if(d.project)openProject(d.project);else if(d.cost)openCost(d.cost);else if(d.addCost)openCost(null,d.addCost);else if(d.action==='new-grant')openGrant();else if(d.action==='new-project')openProject();else if(d.action==='catalog')openCatalog();else if(d.catalog){const r=catalog.find(r=>r.id===d.catalog);$('catalog-dialog').close();openGrant(null,fromCatalog(r,Number($('year').value)||new Date().getFullYear()));}});
for(const id of ['search','stage-filter','priority-filter'])$(id).addEventListener('input',renderGrants);
for(const id of ['year','project-filter'])$(id).addEventListener('change',render);
field($('grant-form'),'projectId').addEventListener('change',()=>{collectDraft();renderAllocations();});
field($('grant-form'),'year').addEventListener('change',()=>{collectDraft();grantProjects();renderAllocations();});
$('catalog-search').addEventListener('input',renderCatalog);
$('backup').onclick=()=>download(JSON.stringify(state,null,2),'application/json','top-manta-matriu-'+today()+'.json');
$('restore').onclick=()=>$('restore-file').click();$('restore-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10000000)throw Error('La còpia supera 10 MB.');const clean=validateState(JSON.parse(await f.text()));if(confirm('Vols substituir tota la matriu d’aquest navegador? S’importaran '+clean.projects.length+' projectes, '+clean.grants.length+' candidatures i '+clean.costs.length+' despeses. Exporta la còpia actual abans si la vols conservar.')){if(save(clean))toast('Matriu importada.');}}catch(err){toast('No s’ha importat: '+err.message);}e.target.value='';};
$('export-csv').onclick=()=>{const k=$('csv-type').value,fn={grants:grantsCSV,projects:projectsCSV,costs:costsCSV,allocations:allocationsCSV}[k];download(fn(view()),'text/csv;charset=utf-8','top-manta-'+k+'-'+today()+'.csv');};
selects($('stage-filter'),STAGES,'Tots els estats');selects($('priority-filter'),PRIORITIES,'Totes les prioritats');render();$('toast').hidden=true;
try{const r=await fetch('../economia/data.json');if(r.ok){const d=await r.json();catalog=d.rows??[];const params=new URLSearchParams(location.search),id=params.get('convocatoria');if(id){const row=catalog.find(r=>r.id===id&&['Subvenció','Beca'].includes(r.kind));if(row){const existing=state.grants.find(g=>g.catalogId===id&&g.year===(Number($('year').value)||new Date().getFullYear()));if(existing)openGrant(existing.id);else openGrant(null,fromCatalog(row,Number($('year').value)||new Date().getFullYear()));}}}}catch{}

